import{z as l,x as t,o as A,c as n,q as B,j as d,D as s,d as e,s as o,S as i,b as E}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"预读","description":"","frontmatter":{"title":"预读","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/readahead.md","filePath":"cs/readahead.md","lastUpdated":1791413859000}'),p={name:"cs/readahead.md"};function c(m,a,D,h,C,u){const r=t("Mermaid");return A(),n("div",null,[a[2]||(a[2]=B('<h1 id="预读" tabindex="-1">预读 <a class="header-anchor" href="#预读" aria-label="Permalink to &quot;预读&quot;">​</a></h1><div class="epigraph"><p>顺序读一旦被认出，内核就在当前请求之后再拉若干页进页缓存，用带宽换掉下一次缺页。</p><footer>—— 据 Paixao 等对 Linux readahead 的实现讨论；Arpaci-Dusseau, <em>OSTEP</em> 对预取的整理；McKusick 对簇读的背景</footer></div><p><a href="/cs/device-nodes">上一课</a>已能打开块设备或文件。每次 <code>read</code> 若只填一页，HDD 与即便是 NVMe 也会把延迟付 N 次。<a href="/cs/page-cache">页缓存</a> 的 miss 路径可以<strong>多填</strong>。缺口是预读窗口：何时放大、何时停、<code>fadvise</code> 如何提示。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>随机读预取会害：把有用页挤出，还占用设备队列。内核跟踪某文件描述的顺序程度，命中则把 readahead 窗口加倍，直到上限；探测失败则收缩。<code>posix_fadvise(WILLNEED/SEQUENTIAL/RANDOM)</code> 改策略。缺口：mmap 顺序扫描同样走异步预读；<a href="/cs/sparse-files">稀疏</a> 洞不应把后面数据当顺序；<code>O_DIRECT</code> 绕过页缓存则本课对象不在。</p><p><span class="marginnote">直觉类比：预读像便利店备货——观察到顾客整箱买水，就把一整箱提前搬上货架（放大窗口）；发现大家都是拿一瓶就走，就别囤货（收缩窗口），否则货架被占满、真正热销的反而放不下。内核盯的是你的「读法」，不是你的意图。</span></p><p><span class="marginnote">窗口以页计，背后可能合并成一次大 I/O。预读是启发式，不是 POSIX 保证。本课不把 madvise 的全部体系写成虚存百科。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>read</code> miss：提交当前页 I/O，同时对后续偏移 <code>readpages</code>。完成的页插入树，标 readahead 以便统计命中。写不预读。对照磁盘调度：预读制造顺序大请求，<a href="/cs/blk-schedulers">块层</a> 更易合并——那是下一课序。对照 NFS：预读变成超前 READ RPC，语义仍受缓存约束。</p><p><span class="marginnote">数字实例：页大小 4KB 时，窗口从 16 页起步、每次命中翻倍——16、32、64 直到上限，一次 64 页预读就是 256KB 的连续读。对一个 1GB 的文件顺序扫描，它把约 26 万次缺页合并成约 4000 次大 I/O，延迟几乎全部消失，只剩带宽开销。</span></p>',10)),(A(),d(i,null,{default:s(()=>[o(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20SEQ%5B%22%E8%AE%A4%E5%87%BA%E9%A1%BA%E5%BA%8F%E8%AF%BB%22%5D%20--%3E%20WIN%5B%22%E6%94%BE%E5%A4%A7%E7%AA%97%E5%8F%A3%22%5D%0A%20%20WIN%20--%3E%20IO%5B%22%E5%BC%82%E6%AD%A5%E5%A1%AB%E5%90%8E%E7%BB%AD%E9%A1%B5%22%5D%0A%20%20IO%20--%3E%20CACHE%5B%22%E9%A1%B5%E7%BC%93%E5%AD%98%22%5D%0A%20%20RAND%5B%22%E9%9A%8F%E6%9C%BA%E6%A8%A1%E5%BC%8F%22%5D%20--%3E%20OFF%5B%22%E5%85%B3%E9%97%AD%E6%88%96%E6%94%B6%E7%BC%A9%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"预读把「文件是流」的统计结构变成 I/O 形状：顺序工作负载接近设备带宽，随机工作负载不应被好心伤害。它不改变崩溃一致性，只改变热页集合。不要把预读写成 CPU 硬件预取器的同构课：缺的是毫秒级存储，不是纳秒级 cache line。",-1)),a[5]||(a[5]=E("p",null,[e("与 "),E("a",{href:"/cs/fs-mmap-coherence"},"mmap 一致"),e("：fault 路径同样可以触发文件预读，共享同一窗口记账。")],-1)),a[6]||(a[6]=E("p",null,[e("实现上：异步预读完成时若用户已改成随机模式，多读的页仍插入 Cache，可能挤热点。mmap 顺序故障用同一套窗口，但 vma 跨越文件空洞要停。 读法上只引用"),E("a",{href:"/cs/device-nodes"},"上一课"),e("的结论，不把对象换成训练推理或限价簿。")],-1)),(A(),d(i,null,{default:s(()=>[o(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20S1%5B%22%E9%A6%96%E6%AC%A1%E8%AF%BB%EF%BC%9A%E7%AA%97%E5%8F%A3%E4%BB%8E%E6%9C%80%E5%B0%8F%E5%80%BC%E8%B5%B7%E6%AD%A5%22%5D%20--%3E%20S2%7B%22%E5%90%8E%E7%BB%AD%E8%AF%BB%E5%91%BD%E4%B8%AD%E9%A2%84%E8%AF%BB%E9%A1%B5%E4%BA%86%E5%90%97%EF%BC%9F%22%7D%0A%20%20S2%20--%3E%7C%22%E5%91%BD%E4%B8%AD%E4%B8%94%E4%BB%8D%E6%98%AF%E9%A1%BA%E5%BA%8F%22%7C%20G%5B%22%E7%AA%97%E5%8F%A3%E5%8A%A0%E5%80%8D%EF%BC%8C%E7%9B%B4%E8%87%B3%E4%B8%8A%E9%99%90%22%5D%0A%20%20G%20--%3E%20IO%5B%22%E5%BC%82%E6%AD%A5%E9%A2%84%E5%8F%96%E6%9B%B4%E5%A4%9A%E9%A1%B5%22%5D%0A%20%20IO%20--%3E%20S2%0A%20%20S2%20--%3E%7C%22%E6%9C%AA%E5%91%BD%E4%B8%AD%EF%BC%8C%E5%83%8F%E9%9A%8F%E6%9C%BA%E8%AF%BB%22%7C%20SH%5B%22%E7%AA%97%E5%8F%A3%E6%94%B6%E7%BC%A9%E7%94%9A%E8%87%B3%E5%85%B3%E9%97%AD%22%5D%0A%20%20SH%20--%3E%20COST%5B%22%E7%9C%81%E4%B8%8B%E5%B8%A6%E5%AE%BD%EF%BC%8C%E4%BD%86%E4%B8%8B%E6%AC%A1%E7%BC%BA%E9%A1%B5%E8%A6%81%E4%BB%98%E5%85%A8%E4%BB%B7%22%5D%0A"})]),fallback:s(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=B('<p><span class="marginnote">常见误区：初学者容易把 <code>posix_fadvise(RANDOM)</code> 理解成「立即把已预读的页作废」。实际异步预取在途中照样完成入缓存，只是<strong>之后</strong>不再放大窗口——多读进来的页会暂时挤占缓存。同理 fadvise 是提示不是命令，内核可以采纳也可以忽略。</span></p><p>本课在操作系统进阶的「文件系统实现 / 接口进阶」课序里，对象是 <strong>预读</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入块层 <code>iostat</code> 的全部指标。不保证跨文件的全局预读调度。下一课故意关掉这层缓存：<code>O_DIRECT</code>。</p><p>版本字段会变，课序钉的是机制对象「预读」，不是某一主线内核的结构体名。 后课默认：顺序读可被启发式预取。绕过页缓存的对齐 I/O，下一课 O_DIRECT。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>预读按顺序度放大窗口，把后续页填进页缓存。</li><li>提示与随机模式可关掉它。</li><li>直接 I/O 是下一课。</li><li>出处：Linux readahead；<em>OSTEP</em>；McKusick 簇读。</li></ul>',8))])}const _=l(p,[["render",c]]);export{F as __pageData,_ as default};
